package com.example.phishsim;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component public class SecurityHeadersFilter extends OncePerRequestFilter{protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain c)throws ServletException,IOException{r.setHeader("Content-Security-Policy","default-src 'self'; style-src 'self'; img-src 'self'; form-action 'self'; frame-ancestors 'none'");r.setHeader("Referrer-Policy","no-referrer");r.setHeader("Permissions-Policy","camera=(), microphone=(), geolocation=()");r.setHeader("X-Content-Type-Options","nosniff");c.doFilter(q,r);}}
